INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6077, 466532, 'tt6613878', NULL, 'Clara', 'Clara', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/uaWAjD4y64qkvGzgNNj9vDrjX2l.jpg', 'https://image.tmdb.org/t/p/original/kuJD5yl1IoKB29cdohzSE24S5bQ.jpg', 'An astronomer becomes obsessed with searching the cosmos for signs of life beyond Earth which leads to a shocking discovery.', NULL, NULL, 1.948, 7.4, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6078, 2044, 'tt0410297', NULL, 'The Lake House', 'The Lake House', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/tHpc1118dYWLnHZleGhwZxRbpae.jpg', 'https://image.tmdb.org/t/p/original/cvenzPOcYthevmYvy0WX4pZ2RNp.jpg', 'When architect Alex Wyler moves into an unusual glass house on stilts over a lake, he discovers a note from the previous tenant in the mailbox--but no one''s lived in the house for years. He replies and soon discovers that he''s corresponding with a doctor named Kate Forster. Their correspondence, only through the ''magical'' mailbox, turns romantic and their paths cross in unexpected ways, but when they try to truly connect, danger looms. They must try to unravel the mystery behind their extraordinary romance before it''s too late.', NULL, NULL, 4.7737, 7.032, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6079, 12650, 'tt0282599', NULL, 'Il Mare', '시월애', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/csJ2BCbQaaNL4n8dk3W91QiAWmV.jpg', 'https://image.tmdb.org/t/p/original/vd3jQVFeFo8pFlhKlZdHWyqmB4K.jpg', 'A man and a woman realize they are separated by two years of time when they exchange letters from different years in a mailbox.', NULL, NULL, 1.8877, 7.4, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6080, 37672, 'tt0078199', NULL, 'Same Time, Next Year', 'Same Time, Next Year', 'movie', 1978, 'https://image.tmdb.org/t/p/w500/58un6toArCEcOfctQ5a2fuQrm4o.jpg', 'https://image.tmdb.org/t/p/original/g3yCzSnN5z6EvwdbQN4ncRuHr08.jpg', 'A man and woman meet by chance at a romantic inn over dinner and, although both are happily married to others, they find themselves in the same bed the next morning questioning how this could have happened. They agree to meet on the same weekend each year—in the same hotel room—and the years pass each has some personal crisis that the other helps them through, often without both of them understanding what is going on.', NULL, NULL, 1.4042, 6.46, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6081, 12150, 'tt0098273', NULL, 'Sea of Love', 'Sea of Love', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/vJ88WmJ12eAK9CRb3cggn9CJthH.jpg', 'https://image.tmdb.org/t/p/original/8she0UIhlxoUnzWhO5AZpPlL0uf.jpg', 'Seen-it-all New York detective Frank Keller is unsettled - he has done twenty years on the force and could retire, and he hasn''t come to terms with his wife leaving him for a colleague. Joining up with an officer from another part of town to investigate a series of murders linked by the lonely hearts columns he finds he is getting seriously and possibly dangerously involved with Helen, one of the main suspects.', NULL, NULL, 3.8955, 6.601, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6082, 76487, 'tt1560985', NULL, 'The Devil Inside', 'The Devil Inside', 'movie', 2012, 'https://image.tmdb.org/t/p/w500/mtyFRIRBmrCE2XKU5EnEK8dtu2X.jpg', 'https://image.tmdb.org/t/p/original/5Ao48b5Fo3yBj5jHuQlpsLaC9JR.jpg', 'In Italy, a woman becomes involved in a series of unauthorized exorcisms during her mission to discover what happened to her mother, who allegedly murdered three people during her own exorcism.', NULL, NULL, 1.6239, 4.688, 0, 1.04, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6083, 758323, 'tt13375076', NULL, 'The Pope''s Exorcist', 'The Pope''s Exorcist', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/jFC4LS5qTAT3PinzdEzINfu1CV9.jpg', 'https://image.tmdb.org/t/p/original/3oqmk6mNWPatBKcjOOJLp5WW9zN.jpg', 'Father Gabriele Amorth, Chief Exorcist of the Vatican, investigates a young boy''s terrifying possession and ends up uncovering a centuries-old conspiracy the Vatican has desperately tried to keep hidden.', NULL, NULL, 7.2389, 6.921, 0, 1.04, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6084, 48171, 'tt1161864', NULL, 'The Rite', 'The Rite', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/gRTxM95huMwIDfZBJWjuifMTfpx.jpg', 'https://image.tmdb.org/t/p/original/qJxSCLGqkSdlvDBIbPqCnCnvV70.jpg', 'Seminary student Michael Kovak reluctantly attends exorcism school at the Vatican. While he’s in Rome, Michael meets an unorthodox priest who introduces him to the darker side of his faith, uncovering the devil’s reach even to one of the holiest places on Earth.', NULL, NULL, 5.5187, 6.123, 0, 2.015, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6085, 974576, 'tt20215234', NULL, 'Conclave', 'Conclave', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/m5x8D0bZ3eKqIVWZ5y7TnZ2oTVg.jpg', 'https://image.tmdb.org/t/p/original/eZzNdjNDvaSoyywy9ICg2UmFwul.jpg', 'After the unexpected death of the Pope, Cardinal Lawrence is tasked with managing the covert and ancient ritual of electing a new one. Sequestered in the Vatican with the Catholic Church’s most powerful leaders until the process is complete, Lawrence finds himself at the center of a conspiracy that could lead to its downfall.', NULL, NULL, 14.5451, 7.187, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6086, 11342, 'tt0098622', NULL, 'Warlock', 'Warlock', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/1QHjr4lBd3vBN4kEqdDFlnJbsa7.jpg', 'https://image.tmdb.org/t/p/original/tVQjkTxxg7t17Fgp4qyii89pCH2.jpg', 'In 17th century New England, witch hunter Giles Redferne captures an evil warlock, but the conjurer eludes death with supernatural help. Flung into the future, the warlock winds up in the 1980s and plans to bring about the end of the world. Redferne follows the enchanter into the modern era and continues his mission, but runs into trouble in such unfamiliar surroundings. With the help of a young woman, can Redferne finally defeat the warlock?', NULL, NULL, 2.9619, 6.288, 0, 9.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
