INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6088, 13787, 'tt0144715', NULL, 'Holy Smoke', 'Holy Smoke', 'movie', 1999, 'https://image.tmdb.org/t/p/w500/xcovgjKOnNsJTz8uADbCVF98wS1.jpg', 'https://image.tmdb.org/t/p/original/2BzfOwehPOdnAm4puhTU52EIICr.jpg', 'While on a journey of discovery in exotic India, beautiful young Ruth Barron falls under the influence of a charismatic religious guru. Her desperate parents then hire PJ Waters, a macho cult de-programmer who confronts Ruth in a remote desert hideaway. But PJ quickly learns that he''s met his match in the sexy, intelligent and iron-willed Ruth.', NULL, NULL, 1.8563, 5.686, 0, 9.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
