INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6090, 50108, 'tt0470402', NULL, 'Sars Wars: Bangkok Zombie Crisis', 'ขุนกระบี่ ผีระบาด', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/tVhap8qkRWRXCypBJyltcn40bol.jpg', 'https://image.tmdb.org/t/p/original/fpitfcmeOWko7rM5ih1jHXwOeDd.jpg', 'In the wake of a deadly SARS outbreak that''s turned ordinary folks into flesh-eating zombies, Thailand stands alone as the only nation to block the pandemic. That is, until the virus finds its way into a crowded Bangkok apartment complex.', NULL, NULL, 0.766, 6.019, 0, 9.02, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
