INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6092, 66664, 'tt0098321', NULL, 'Shocking Dark', 'Terminator 2', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/tztmdSyvfvQBVyzqyh6sKQeJP5g.jpg', 'https://image.tmdb.org/t/p/original/b4oyUTJzHQ4Q2CNoDYtvFJkm29q.jpg', 'In a polluted future Venice researchers work to improve the situation. One day, unknown forces start killing them. A team of soldiers and a couple of civilians is sent to investigate. Soon, they encounter strange murderous creatures.', NULL, NULL, 0.6439, 4.5, 0, 9.05, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6093, 618344, 'tt11079148', NULL, 'Justice League Dark: Apokolips War', 'Justice League Dark: Apokolips War', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/c01Y4suApJ1Wic2xLmaq1QYcfoZ.jpg', 'https://image.tmdb.org/t/p/original/miChhr7EXynB2R5JLvMcz2oBgi2.jpg', 'Earth is decimated after intergalactic tyrant Darkseid has devastated the Justice League in a poorly executed war by the DC Super Heroes. Now the remaining bastions of good – the Justice League, Teen Titans, Suicide Squad and assorted others – must regroup, strategize and take the war to Darkseid in order to save the planet and its surviving inhabitants.', NULL, NULL, 5.1484, 8.193, 0, 9.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6094, 19287, 'tt0116861', NULL, 'Leprechaun 4: In Space', 'Leprechaun 4: In Space', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/2nt0095grCSepz6xU24a5yP5mwc.jpg', 'https://image.tmdb.org/t/p/original/euRQW8POblTtEVy19JLFzJlWObI.jpg', 'On a planet in a distant galaxy, a power hungry Leprechaun, holds a beautiful alien princess hostage in order to marry her for her royal title. With her title and his beloved gold, he''ll be able to rule the universe. While making his maniacal plans, what he doesn''t count on is an invading platoon of marines from Earth, to save the princess and foil his plans. An accomplished trickster, the Leprechaun stows himself away on the orbiting spaceship and wreaks havoc on the crew in an attempt to recapture his bride.', NULL, NULL, 2.3472, 4.608, 0, 9.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6095, 384521, 'tt2548396', NULL, 'The Cloverfield Paradox', 'The Cloverfield Paradox', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg', 'https://image.tmdb.org/t/p/original/2cnUCcNmmj79hGmimvWlUo5P2K8.jpg', 'Orbiting above a planet on the brink of war, scientists test a device to solve an energy crisis and end up face-to-face with a dark alternate reality.', NULL, NULL, 4.9911, 5.638, 0, 9.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6096, 195757, 'tt1778924', NULL, 'The Ultimate Life', 'The Ultimate Life', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/lRjea5SWCiKzDIpgNDzyvyOSTp.jpg', 'https://image.tmdb.org/t/p/original/kc7EqzuZVtwxCgmqjj1Lv5ISTsS.jpg', 'Despite his best intentions, billionaire Jason Stevens can’t find enough time to keep his beloved Alexia a priority. But when he discovers his late grandfather’s journal, he is transported back to Red Stevens’ incredible world. With everything he loves hanging in the balance, Jason Stevens hopes the past will prepare him well for the future.', NULL, NULL, 2.8289, 6.9, 0, 9.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6097, 83533, 'tt1757678', NULL, 'Avatar: Fire and Ash', 'Avatar: Fire and Ash', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/bRBeSHfGHwkEpImlhxPmOcUsaeg.jpg', 'https://image.tmdb.org/t/p/original/sdZSjtGUTSN8B3al5o0f2WoQfQQ.jpg', 'In the wake of the devastating war against the RDA and the loss of their eldest son, Jake Sully and Neytiri face a new threat on Pandora: the Ash People, a violent and power-hungry Na''vi tribe led by the ruthless Varang. Jake''s family must fight for their survival and the future of Pandora in a conflict that pushes them to their emotional and physical limits.', NULL, NULL, 103.2057, 7.634, 0, 9.53, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6098, 24230, 'tt0107668', NULL, 'Nemesis', 'Nemesis', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/znPIbermRgSXgjArNxhO8mb0Ba6.jpg', 'https://image.tmdb.org/t/p/original/dTyneeUtfK1h8t48lNX8M5geJxf.jpg', 'In the future, chaos is rampant as ''information terrorists'' threaten to destroy order in society. Alex is a part-man, part-machine LAPD cop who is the best at what he does. When one of the terrorists calls him a machine, Alex questions his humanity and decides to leave the force. His final assignment is to apprehend an old colleague who has stolen some data. However, there is more than meets the eye and Alex must question his allegiance.', NULL, NULL, 2.8244, 5.429, 0, 10.26, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
