INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6100, NULL, NULL, 4754, 'Alien: Isolation', 'Alien: Isolation', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1vzu.jpg', NULL, 'Alien: Isolation is a survival horror game based on the Alien franchise. As Amanda Ripley, daughter of Ellen Ripley, you will navigate through an increasingly volatile world as you find yourself confronted on all sides by a panicked population and an unpredictable Alien. You must scavenge resources, improvise solutions and use your wits, not just to succeed in your mission but to simply stay alive. In addition to the main story mode there''s Survivor mode in which the player needs to escape from a specially designed map fulfilling secondary objectives along the way, while being aggressively hunted by the alien. This mode includes online leaderboards.', 'https://www.igdb.com/games/alien-isolation', '["PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 9.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
