INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6122, 60874, 'tt3158246', NULL, 'Space Dandy', 'スペース☆ダンディ', 'tv', 2014, 'https://image.tmdb.org/t/p/w500/yNjRKE4W2ZJIoCDA2o6brNqpjg7.jpg', 'https://image.tmdb.org/t/p/original/o5P2aI2MKuMYZIP5YO3ahVMBaOh.jpg', 'Space Dandy is a dandy in space! This dreamy adventurer with a to-die-for pompadour travels across the galaxy in search of aliens no one has ever laid eyes on. Each new species he discovers earns him a hefty reward, but this dandy has to be quick on his feet because it’s first come – first served! Accompanied by his sidekicks, a rundown robot named QT and Meow the cat-looking space alien, Dandy bravely explores unknown worlds inhabited by a variety aliens. Join the best dressed alien hunter in all of space and time as he embarks on an adventure that ends at the edge of the universe!', NULL, NULL, 10.3099, 7.544, 0, 3.02, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6123, NULL, NULL, 6893, 'Super Monkey Ball 3D', 'Super Monkey Ball 3D', 'game', 2011, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5j9r.jpg', NULL, 'Taking advantage of the power of the Nintendo 3DS, players can let themselves loose in each new vibrant world as they twist and turn whilst aiming to collect every banana in the fastest time possible. This latest installment contains three brand-new compelling gameplay choices including single-player puzzle levels, Monkey Race and Monkey Fight. These new game modes give players the chance to compete via wireless connection with up to four players in the best 3D social experience possible in the palm of their hands. In addition, Super Monkey Ball fans will be able to choose between the Nintendo 3DS motion sensor or the Slide Pad to navigate the puzzle mazes with complete precision.', 'https://www.igdb.com/games/super-monkey-ball-3d', '["Nintendo 3DS"]', NULL, NULL, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
