INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6165, 14306, 'tt0822832', NULL, 'Marley & Me', 'Marley & Me', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/pnB6hjTKylb0Ve2nUWt16gzkErr.jpg', 'https://image.tmdb.org/t/p/original/tVoWbAAfTDIhTeo78SbA2V6mv8E.jpg', 'A newly married couple, in the process of starting a family, learn many of life''s important lessons from their trouble-loving retriever, Marley. Packed with plenty of laughs to lighten the load, the film explores the highs and lows of marriage, maturity and confronting one''s own mortality, as seen through the lens of family life with a dog.', NULL, NULL, 5.1524, 7.178, 0, 1.05, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
