INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6190, 6967, 'tt0436889', NULL, 'The White Masai', 'Die weisse Massai', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/7hNAYqhwmVYtvxgSZFiKmWJDClP.jpg', 'https://image.tmdb.org/t/p/original/jhPVZsEQYG4cLJ5IJV7J1n3bcQa.jpg', 'A girl, Carola, whose vacation in Kenya takes an interesting turn when she becomes infatuated with a Masai. Carola decides to leave her boyfriend to stay with her lover. There, she has to adapt to the Masai''s way of life and get used to their food which includes milk mixed with blood. She also has to face her husband''s attitude towards women and what he expects from a wife. Nonetheless, Carola is welcomed warmly into the tribe she has chosen to join.', NULL, NULL, 3.9491, 6.281, 0, 10.52, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6191, 232672, 'tt1086772', NULL, 'Blended', 'Blended', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/o2YrH9jS7CAfWjETHFeL0tth79E.jpg', 'https://image.tmdb.org/t/p/original/g5haoqEqt5VwVwQKEkoXY9zqSxb.jpg', 'Recently divorced mom Lauren and widowed dad Jim let their friends push them into a blind date, which goes disastrously wrong. Unsurprisingly, neither wants to see the other ever again. However, fate intervenes when both Jim and Lauren, unbeknownst to each other, purchase one-half of the same vacation package at a South African resort for families, during spring break. They and their children are forced to share the same romantic suite and participate in a slew of family activities together.', NULL, NULL, 7.0953, 6.896, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
