INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6193, 776506, 'tt11378876', NULL, 'The Blazing World', 'The Blazing World', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/s18H9aU7yT91U2XPAc2a3UxldA7.jpg', 'https://image.tmdb.org/t/p/original/yJpGFmoVsDKrVcXSyGf5HTx9i98.jpg', 'Ever since Margaret was six years old, she has been haunted by the memory of watching her sister drown during an explosive fight between her parents. As a young woman, she slides further into her twisted inner life, ultimately finding herself on the brink of suicide. Through an epic journey down the smokiest and scariest corridors of her imagination, she tries to exorcise the demons pushing her closer and closer to the edge.', NULL, NULL, 0.9577, 4.3, 0, 1.03, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
