INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6195, 404245, 'tt4528454', NULL, 'Starfish', 'Starfish', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/ysjAdklkfNlQ7t6CCf3QwgU5oU6.jpg', 'https://image.tmdb.org/t/p/original/uh3Zb9M1nVwf1nXbu8Dz8NO08vE.jpg', 'Based on the real story of Tom and Nicola Ray from Rutland. Their perfect life is totally ruined in a single moment after Tom had developed sepsis. While her husband was in coma, Nicola gave birth to their second child on the other side of the same hospital. Within a matter of days, sepsis would rob Tom of both his arms and legs, and left his face severely disfigured. As an ordinary man, Tom never put himself at risk — he just woke up two months later in a nightmare, a face-off quadruple amputee... This incredible story of survival shows what can be overcome when love is unconditional.', NULL, NULL, 0.8274, 6.568, 0, 1.02, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
