INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6242, 8998, 'tt0436331', NULL, 'Friends with Money', 'Friends with Money', 'movie', 2006, 'https://image.tmdb.org/t/p/w500/8WdKFowmvfxmDJP5uS0Mf7kdskO.jpg', 'https://image.tmdb.org/t/p/original/6ReVMJu87CMRH9ev0Py82weI1ro.jpg', 'As she reaches her mid-thirties and quits her lucrative job, singleton Olivia finds herself unsure about her future and her relationships with her successful and wealthy friends. She begins to envy the security of her richer friends and, although their lives may seem easier, Olivia''s friends have their problems too: screenwriters Christine and Patrick are unable to collaborate on their latest project, Jane and Aaron have lost the romance in their relationship, and Franny and Matt have difficulties handling the demands of parenthood.', NULL, NULL, 1.8324, 5.146, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
