INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6328, 6917, 'tt0093075', NULL, 'The Gate', 'The Gate', 'movie', 1987, 'https://image.tmdb.org/t/p/w500/ik7AfGWpwKnjaQeth3LZqrqzvfB.jpg', 'https://image.tmdb.org/t/p/original/vxRUX12ZXoTwffLcqS7RAZqcknj.jpg', 'Three young children accidentally release a horde of nasty, pint-sized demons from a hole in a suburban backyard. What follows is a classic battle between good and evil as the three kids struggle to overcome a nightmarish hell that is literally taking over the Earth.', NULL, NULL, 2.6533, 6.077, 0, 10.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6329, 463821, 'tt2119543', NULL, 'The House with a Clock in Its Walls', 'The House with a Clock in Its Walls', 'movie', 2018, 'https://image.tmdb.org/t/p/w500/qM66Hv4ByAxnilr0jaqCA9uOD4Y.jpg', 'https://image.tmdb.org/t/p/original/tQvvRReWhrXnj28s4AIp2PblByg.jpg', 'When ten-year-old Lewis is suddenly orphaned, he is sent to live with his Uncle Jonathan in a creaky (and creepy) old mansion with a mysterious ticking noise that emanates from the walls. Upon discovering that his uncle is a warlock, Lewis begins learning magic, but when he rebelliously resurrects an evil warlock he must find the secret of the house and save the world from destruction.', NULL, NULL, 4.1561, 6.253, 0, 10.02, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6330, 11655, 'tt0104029', NULL, 'Cronos', 'Cronos', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/tQqIA8bDN7v1LmHjJg7Qh9BKCLa.jpg', 'https://image.tmdb.org/t/p/original/nR16suoZalsNzJvtkN8nxsTVwrR.jpg', 'Faced with his own mortality, an ingenious alchemist tried to perfect an invention that would provide him with the key to eternal life. It was called the Cronos device. When he died more than 400 years later, he took the secrets of this remarkable device to the grave with him. Now, an elderly antiques dealer has found the hellish machine hidden in a statue and learns about its incredible powers. The more he uses the device, the younger he becomes...but nothing comes without a price. Life after death is just the beginning as this nerve-shattering thriller unfolds and the fountain of youth turns bloody.', NULL, NULL, 2.5658, 6.678, 0, 11.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
