INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6332, 9092, 'tt0119227', NULL, 'Snow White: A Tale of Terror', 'Snow White: A Tale of Terror', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/rpOd7AHqRuKA8Da3WcE1U4ACmp2.jpg', 'https://image.tmdb.org/t/p/original/jrm5WPcYN09Xv9u31XwATd0R7Rv.jpg', 'When young Lili''s mother dies in childbirth, her father remarries Lady Claudia, a woman ruled by an evil mirror with the power to make her queen of all living things.  After escaping an attempt on her life, Lili finds herself lost in a dark forest, where living happily ever after seems unlikely.', NULL, NULL, 2.4507, 6.096, 0, 10.02, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6333, 508947, 'tt8097030', NULL, 'Turning Red', 'Turning Red', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/qsdjk9oAKSQMWs0Vt5Pyfh6O4GZ.jpg', 'https://image.tmdb.org/t/p/original/fOy2Jurz9k6RnJnMUMRDAgBwru2.jpg', 'Thirteen-year-old Mei is experiencing the awkwardness of being a teenager with a twist – when she gets too excited, she transforms into a giant red panda.', NULL, NULL, 20.4856, 7.333, 0, 1.05, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
