INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6335, 49521, 'tt0770828', NULL, 'Man of Steel', 'Man of Steel', 'movie', 2013, 'https://image.tmdb.org/t/p/w500/8GFtkImmK0K1VaUChR0n9O61CFU.jpg', 'https://image.tmdb.org/t/p/original/j2MlEEpA3wgwQiJB6p1UHC50oiw.jpg', 'A young boy learns that he has extraordinary powers and is not of this earth. As a young man, he journeys to discover where he came from and what he was sent here to do. But the hero in him must emerge if he is to save the world from annihilation and become the symbol of hope for all mankind.', NULL, NULL, 17.412, 6.654, 0, 7.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6336, NULL, NULL, 999, 'Oddworld: Abe''s Oddysee', 'Oddworld: Abe''s Oddysee', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co89fk.jpg', NULL, 'Oddworld: Abe''s Oddysee is the first game set in the fictional Oddworld universe. It is a platformer with puzzle-solving elements, focusing on the portrayal of a weak, underpowered character in a grim and hostile world, who has to rely on his cunning to outwit enemies and overcome hazards. The game has pre-rendered background graphics and uses CG movies of similar style to advance the story between the levels.

The main character Abe is almost completely helpless: he cannot use weapons and is usually instantly killed by his brutal enemies if he confronts them directly. For this reason, most of the game involves careful exploration, timed movement, sneaking, and outsmarting the foes through various means: throwing stones to confuse them, luring them into traps, etc. Abe can run, jump, climb, tiptoe, crouch, and roll; in most areas these actions are essential to his survival. A few stages involve Abe riding a large animal known as Elum.

Abe''s only special power is chanting, which he can use to stun certain enemies for a while or possess them. When Abe possess an enemy he gains his abilities: for example, possessing the body or a ferocious Slig allows the player to shoot from his machine gun, communicate with other creatures of his kind, and even commit suicide, clearing the way for Abe.', 'https://www.igdb.com/games/oddworld-abe-s-oddysee', '["OnLive Game System", "PlayStation 3", "PC (Microsoft Windows)", "DOS", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 9.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6337, NULL, NULL, 9174, 'Little Nightmares', 'Little Nightmares', 'game', 2017, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rdi.jpg', NULL, 'Little Nightmares is a puzzle-platform horror adventure game developed by Tarsier Studios and published by Bandai Namco Entertainment. Set in a mysterious world, Little Nightmares follows the journey of Six, a hungry little girl who must escape the Maw, an iron vessel inhabited by monstrous, twisted beings.', 'https://www.igdb.com/games/little-nightmares', '["Google Stadia", "PlayStation 4", "Android", "PC (Microsoft Windows)", "iOS", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 10.53, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6338, NULL, NULL, 314265, 'Reanimal', 'Reanimal', 'game', 2026, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coc21i.jpg', NULL, 'The creators of Little Nightmares I & II have returned to take you on a darker, more terrifying journey than ever before. In this horror adventure game, a brother & sister go through hell to rescue their missing friends and escape the island that they used to call home.', 'https://www.igdb.com/games/reanimal', '["Xbox Series X|S", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 9.03, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6339, NULL, NULL, 148241, 'Lies of P', 'Lies of P', 'game', 2023, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6lxr.jpg', NULL, 'Lies of P is an action role-playing game set in a dark, Belle Époque-inspired city overrun by deadly puppets. Players control Pinocchio, reimagined as a mechanical warrior, navigating a decaying world while making choices that affect the unfolding narrative. The game features challenging melee combat, weapon customization, and a mechanical arm with various abilities.', 'https://www.igdb.com/games/lies-of-p', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Mac", "Xbox One"]', NULL, NULL, 0, 10.51, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6340, 37680, 'tt1632701', NULL, 'Suits', 'Suits', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/vQiryp6LioFxQThywxbC6TuoDjy.jpg', 'https://image.tmdb.org/t/p/original/or0E36KfzJYZwqXeiCfm1JgepKF.jpg', 'While running from a drug deal gone bad, Mike Ross, a brilliant young college-dropout, slips into a job interview with one of New York City''s best legal closers, Harvey Specter. Tired of cookie-cutter law school grads, Harvey takes a gamble by hiring Mike on the spot after he recognizes his raw talent and photographic memory.', NULL, NULL, 109.6633, 8.221, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6341, 9446, 'tt0119432', NULL, 'Jungle 2 Jungle', 'Jungle 2 Jungle', 'movie', 1997, 'https://image.tmdb.org/t/p/w500/xRKfvheWRfkirm0kzdBAydUjiK5.jpg', 'https://image.tmdb.org/t/p/original/1yZPEWvKLVMImVECTgZLKvdYyMa.jpg', 'Uptight New York City executive, Michael Cromwell, pursues his soon-to-be ex-wife to South America and returns home with the son he never knew he had—a boy raised in a tribal village in Brazil. Armed with only his blowgun, the 13-year-old Mimi-Siku discovers that the world outside his jungle home is indeed a strange place.', NULL, NULL, 2.0636, 5.425, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
