INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6343, 13018, 'tt0800240', NULL, 'Deception', 'Deception', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/lfkdTvfmaqlGiHymJl6EAdIaN1J.jpg', 'https://image.tmdb.org/t/p/original/A68agruFq6vg5oYCMFyllmqMsI0.jpg', 'As a corporate auditor who works in a number of different offices, Jonathan McQuarry wanders without an anchor among New York''s power brokers. A chance meeting with charismatic lawyer Wyatt Bose leads to Jonathan''s introduction to The List, an underground sex club. Jonathan begins an affair with a woman known only as S, who introduces Jonathan to a world of treachery and murder.', NULL, NULL, 2.8754, 5.96, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6344, 24249, 'tt0099091', NULL, 'Bad Influence', 'Bad Influence', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/8s4TwiCCBVnikc140osRlhjFFS0.jpg', 'https://image.tmdb.org/t/p/original/c29gQq9hAV2ODfyxb1CoIjZpkGz.jpg', 'Wimpy young executive Michael is about to get pulverized by a jealous boyfriend in a bar when a handsome, mysterious stranger steps in—and then disappears. Later that night, Michael runs into a stranger on a pier, who wheedles his way into Michael''s life and turns it upside down.', NULL, NULL, 1.7958, 5.99, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6345, 11873, 'tt0090863', NULL, 'The Color of Money', 'The Color of Money', 'movie', 1986, 'https://image.tmdb.org/t/p/w500/dVdnHmdQu3JtLAAksjTmTEF76gD.jpg', 'https://image.tmdb.org/t/p/original/hhCp6ZLDjS5wUHkGg7k3VGvH3Xm.jpg', 'Former pool hustler "Fast Eddie" Felson decides he wants to return to the game by taking a pupil. He meets talented but green Vincent Lauria and proposes a partnership. As they tour pool halls, Eddie teaches Vincent the tricks of scamming, but he eventually grows frustrated with Vincent''s showboat antics, leading to an argument and a falling-out. Eddie takes up playing again and soon crosses paths with Vincent as an opponent.', NULL, NULL, 3.2041, 6.85, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
