INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6378, 1245, 'tt0107943', NULL, 'The Remains of the Day', 'The Remains of the Day', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/uDGDtqSvuch324WnM7Ukdp1bCAQ.jpg', 'https://image.tmdb.org/t/p/original/vFhxd3Z1zaV3Yu5XLpvWzSxJCe8.jpg', 'A rule-bound head butler''s world of manners and decorum in the household he maintains is tested by the arrival of a housekeeper who falls in love with him in post-WWI Britain. The possibility of romance and his master''s cultivation of ties with the Nazi cause challenge his carefully maintained veneer of servitude.', NULL, NULL, 4.1553, 7.4, 0, 4.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6379, 975773, 'tt20234774', NULL, 'Wicked Little Letters', 'Wicked Little Letters', 'movie', 2024, 'https://image.tmdb.org/t/p/w500/scAU7YudKNVeZlOfgSEWntAUSJ.jpg', 'https://image.tmdb.org/t/p/original/sp99ZzKz6Zv7nX95XDJmhNA4LVI.jpg', 'When the denizens of Littlehampton – including conservative Edith – begin receiving letters full of hilarious profanities, rowdy Irish migrant Rose is charged with the crime. Suspecting something amiss, the town''s women band together to investigate.', NULL, NULL, 4.0183, 6.923, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6380, 245842, 'tt2328678', NULL, 'The King''s Daughter', 'The King''s Daughter', 'movie', 2022, 'https://image.tmdb.org/t/p/w500/sZ3ZxAjy26ZEo3WM4JFdOkoE5sS.jpg', 'https://image.tmdb.org/t/p/original/o3U4733mGsmieBeqs4Sw2ze6n53.jpg', 'King Louis XIV''s quest for immortality leads him to capture and steal a mermaid''s life force, a move that is further complicated by his illegitimate daughter''s discovery of the creature.', NULL, NULL, 4.0521, 6.985, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6381, 2977, 'tt0416508', NULL, 'Becoming Jane', 'Becoming Jane', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/yHA6JEn57MBGp2yGFgYyopJvk2O.jpg', 'https://image.tmdb.org/t/p/original/r95IP56O3j8fz9a09x55lymr9uJ.jpg', 'Though young Jane Austen''s financially strapped parents expect her to marry the nephew of wealthy Lady Gresham, Jane herself knows that such a union will destroy her creativity and sense of self-worth. Instead, she becomes involved with Tom Lefroy, a charming but penniless apprentice lawyer who gives her the knowledge of the heart she needs for her future career as a novelist.', NULL, NULL, 3.3422, 7.308, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6382, 4584, 'tt0114388', NULL, 'Sense and Sensibility', 'Sense and Sensibility', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/9YdQ73YmvInxpXZVNjEKePw9tRO.jpg', 'https://image.tmdb.org/t/p/original/cFnyfWHL6HjOOVal6lp8e5gqibK.jpg', 'The Dashwood sisters, sensible Elinor and passionate Marianne, learn that their prospects of marriage seem doomed by their family''s sudden loss of fortune. After Henry Dashwood dies unexpectedly, his estate must pass on by law to his son. These circumstances leave Mr. Dashwood''s wife and daughters without a home and with barely enough money to live on. As Elinor and Marianne struggle to find romantic fulfillment in a society obsessed with financial and social status, they must learn to mix sense with sensibility in their dealings with both money and men.', NULL, NULL, 6.1702, 7.425, 0, 3.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6383, 296360, 'tt3068194', NULL, 'Love & Friendship', 'Love & Friendship', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/ptpdUQiRjeHgE1dmpCd38N64ENV.jpg', 'https://image.tmdb.org/t/p/original/ekZ7j7ElSFurRgqSalcP622YGrE.jpg', 'From Jane Austen’s novella, the beautiful and cunning Lady Susan Vernon visits the estate of her in-laws to wait out colorful rumors of her dalliances and to find husbands for herself and her daughter. Two young men, handsome Reginald DeCourcy and wealthy Sir James Martin, severely complicate her plans.', NULL, NULL, 1.8144, 6.042, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6384, 18320, 'tt0962736', NULL, 'The Young Victoria', 'The Young Victoria', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/iGyuReyij3bPCtzJdSjTR8PR0pa.jpg', 'https://image.tmdb.org/t/p/original/28XFhXIlmeg19bSOpWKWaWFBEkQ.jpg', 'As the only legitimate heir of England''s King William, teenage Victoria gets caught up in the political machinations of her own family. Victoria''s mother wants her to sign a regency order, while her Belgian uncle schemes to arrange a marriage between the future monarch and Prince Albert, the man who will become the love of her life.', NULL, NULL, 2.8135, 7.2, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6385, 13189, 'tt0087056', NULL, 'A Christmas Carol', 'A Christmas Carol', 'movie', 1984, 'https://image.tmdb.org/t/p/w500/m3T3iLdE6J5PrqvvP0XNHBvM2bm.jpg', 'https://image.tmdb.org/t/p/original/1WQ4bHXzS7DpGppkS2PcpFvpY7T.jpg', 'Miser Ebenezer Scrooge is awakened on Christmas Eve by spirits who reveal to him his own miserable existence, what opportunities he wasted in his youth, his current cruelties, and the dire fate that awaits him if he does not change his ways. Scrooge is faced with his own story of growing bitterness and meanness, and must decide what his own future will hold: death or redemption.', NULL, NULL, 2.9587, 7.462, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6386, 8293, 'tt0104454', NULL, 'Howards End', 'Howards End', 'movie', 1992, 'https://image.tmdb.org/t/p/w500/1009nhfj28VhhQnVadtjkOacduX.jpg', 'https://image.tmdb.org/t/p/original/novvibtQv0B4psRxuqvd8g2qS5M.jpg', 'A saga of class relations and changing times in an Edwardian England on the brink of modernity, the film centers on liberal Margaret Schlegel, who, along with her sister Helen, becomes involved with two couples: wealthy, conservative industrialist Henry Wilcox and his wife Ruth, and the downwardly mobile working-class Leonard Bast and his mistress Jackie.', NULL, NULL, 3.3909, 6.998, 0, 3.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6387, 250734, 'tt2935476', NULL, 'Far from the Madding Crowd', 'Far from the Madding Crowd', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/cr4cctBPv9qHDtjDps4wi0kqI7h.jpg', 'https://image.tmdb.org/t/p/original/uPyZMwbXLnPrFPmUC9qK7WfLJAW.jpg', 'In Victorian England, the independent and headstrong Bathsheba Everdene attracts three very different suitors: Gabriel Oak, a hardworking young sheep farmer; Frank Troy, a handsome and reckless Sergeant; and William Boldwood, a prosperous and mature bachelor.', NULL, NULL, 3.3341, 7.02, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6388, 980397, 'tt0015394', NULL, 'Tess of the D''Urbervilles', 'Tess of the D''Urbervilles', 'movie', 1924, 'https://image.tmdb.org/t/p/w500/zezQGJjXZgiqIjxD9A3MfIfIgyK.jpg', 'https://image.tmdb.org/t/p/original/4lmJFgdqaWF03CUp0aORBV5tRsp.jpg', 'A young girl is seduced and raped by an older middle class man in Victorian England. After moving on with her path, she gets married. All is well until her husband discovers her past. Leading her on a life of wandering, murder, and execution.', NULL, NULL, 0.3916, 6.5, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6389, 26799, 'tt0110977', NULL, 'The Return of the Native', 'The Return of the Native', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/sBHRyY1eokAr6MXteomI04fHhXp.jpg', 'https://image.tmdb.org/t/p/original/xYf4pndpKq44KUVIwTKEgZKAH0u.jpg', 'Eustacia Vye, an exquisite beauty despairing at her boring life on an English moor, sets up a fateful lovers'' triangle when she uses her wiles to entice two men, a dashing suitor and a successful man who made his name abroad and returned to his home on the heath.', NULL, NULL, 1.2152, 6.289, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
