INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6397, 14022, 'tt0102943', NULL, 'Slacker', 'Slacker', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/f7Iov2nd0XX9bp2laQEPYPEhisc.jpg', 'https://image.tmdb.org/t/p/original/1gjK6oZSQtvhFBbSgkBvn72dPLF.jpg', 'Austin, Texas, is an Eden for the young and unambitious, from the enthusiastically eccentric to the dangerously apathetic. Here, the nobly lazy can eschew responsibility in favor of nursing their esoteric obsessions. The locals include a backseat philosopher who passionately expounds on his dream theories to a seemingly comatose cabbie, a young woman who tries to hawk Madonna''s Pap test to anyone who will listen and a kindly old anarchist looking for recruits.', NULL, NULL, 2.5568, 6.737, 0, 2.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6398, 1364904, 'tt22530226', NULL, 'A Useful Ghost', 'ผีใช้ได้ค่ะ', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/ysCOASLn8SaiFYWZYqNLTdO97NQ.jpg', 'https://image.tmdb.org/t/p/original/5IfH9Itm2WAlfZTuXj5Q9lAS1jV.jpg', 'Worried about her husband being allergic to dust, Nat, a recently-dead woman, returns as a ghost possessing a vacuum cleaner to clean the house and protect her family from other vengeful ghosts in the house. To become a useful ghost, she needs to get rid of the useless ones.', NULL, NULL, 2.7709, 6.5, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
