INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6400, 26564, 'tt0109508', NULL, 'Crumb', 'Crumb', 'movie', 1995, 'https://image.tmdb.org/t/p/w500/9ocTHdBCJdwJ65Tubg3lYlfMxEY.jpg', 'https://image.tmdb.org/t/p/original/1mlfORlfu2PtZnlEB3gMKqJy7Qp.jpg', 'This movie chronicles the life and times of R. Crumb. Robert Crumb is the cartoonist/artist who drew Keep On Truckin'', Fritz the Cat, and played a major pioneering role in the genesis of underground comix. Through interviews with his mother, two brothers, wife, ex-wife and ex-girlfriends, as well as selections from his vast quantity of graphic art, we are treated to a darkly comic ride through one man''s subconscious mind.', NULL, NULL, 2.1165, 7.521, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6401, 2131, 'tt0118298', NULL, 'Daria', 'Daria', 'tv', 1997, 'https://image.tmdb.org/t/p/w500/iEcFbXXnxUS60HT4yFQe7huuajA.jpg', 'https://image.tmdb.org/t/p/original/AelRiewpDPxMiEALf8GtnHxle9b.jpg', 'After moving to a new town with her stressed-out parents and relentlessly popular little sister, Daria uses her acerbic wit and keen powers of observation to contend with the mind-numbingly ridiculous world of Lawndale High.', NULL, NULL, 12.1156, 8.243, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
