INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6414, 951, 'tt0099938', NULL, 'Kindergarten Cop', 'Kindergarten Cop', 'movie', 1990, 'https://image.tmdb.org/t/p/w500/nKnHWwkXyvhzCYWm3FyRAv3qBrl.jpg', 'https://image.tmdb.org/t/p/original/qWP5TlH1448Pt9ayyuLZJY0NXWj.jpg', 'Hard-edged cop John Kimble gets more than he bargained for when he goes undercover as a kindergarten teacher to get the goods on a brutal drug lord while at the same time protecting the man''s young son. Pitted against a class of boisterous moppets whose antics try his patience and test his mettle, Kimble may have met his match … in more ways than one.', NULL, NULL, 3.207, 6.128, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6415, NULL, NULL, 1276, 'Deadly Premonition', 'Deadly Premonition', 'game', 2010, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobmod.jpg', NULL, 'Playing as special agent Francis York Morgan (call him York – everyone else does), it’s your job to investigate the brutal murder of a young local beauty in the town of Greenvale. Amidst the backdrop of soaring mountains and a small American suburb, York must solve the mystery of the Red Seed Murders and stay alive in a place where supernatural creatures and a mysterious raincoat-clad, axe-wielding killer seek to end his investigation for good.

Part suspense-filled horror, part action-adventure game, Deadly Premonition offers an open-world experience packed with locals to meet and places to discover, as well as numerous side quests and mini-games that will help you solve the murders and uncover Greenvale’s deepest, darkest secrets.', 'https://www.igdb.com/games/deadly-premonition', '["PlayStation 3", "Xbox 360"]', NULL, NULL, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
