INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6419, 1447, 'tt0491738', NULL, 'Psych', 'Psych', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/fDI15gTVbtW5Sbv5QenqecRxWKJ.jpg', 'https://image.tmdb.org/t/p/original/sh7GRlX4d7j3XSTeyGZnlKqkHGk.jpg', 'Thanks to his police officer father''s efforts, Shawn Spencer spent his childhood developing a keen eye for detail (and a lasting dislike of his dad). Years later, Shawn''s frequent tips to the police lead to him being falsely accused of a crime he solved.

Now, Shawn has no choice but to use his abilities to perpetuate his cover story: psychic crime-solving powers, all the while dragging his best friend, his dad, and the police along for the ride.', NULL, NULL, 74.6785, 7.889, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
