INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6464, 8882, 'tt0929425', NULL, 'Gomorrah', 'Gomorra', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/3XcCTqSovFZE5GRebJmh1kHwziw.jpg', 'https://image.tmdb.org/t/p/original/dmxAEDURAwfz6iTXTWu1GCYcOR3.jpg', 'An inside look at Italy''s modern-day crime families, the Camorra in Naples and Caserta. Based on a book by Roberto Saviano. Power, money and blood: these are the "values" that the residents of the Province of Naples and Caserta have to face every day. They hardly ever have a choice and are forced to obey the rules of the Camorra. Only a lucky few can even think of leading a normal life.', NULL, NULL, 2.2243, 6.877, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
