INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6467, NULL, NULL, 393025, 'Final Fantasy VII', 'Final Fantasy VII', 'game', 1997, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobny6.jpg', NULL, 'Final Fantasy VII (note: this is the original Japan-exclusive version) is a role-playing game set in a post-modern, steampunk world where technology and fantasy elements coexist. Players control Cloud Strife, an ex-soldier who joins the eco-terrorist group AVALANCHE to oppose Shinra Inc., a corporation draining the planet''s life energy. The game features turn-based combat with an active time element, a customizable Materia system for abilities, and unique Limit Break attacks for each character. Players explore 3D environments, engage in various mini-games, and uncover a complex plot involving Cloud''s mysterious past and a powerful threat to the world. As the story progresses, players gain access to different vehicles, allowing them to explore new areas and uncover additional content.', 'https://www.igdb.com/games/final-fantasy-vii--12', '["PlayStation"]', NULL, NULL, 0, 9.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
