INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6469, NULL, NULL, 7605, 'S.T.A.L.K.E.R.: Call of Pripyat', 'S.T.A.L.K.E.R.: Call of Pripyat', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa4r9.jpg', NULL, 'The events of S.T.A.L.K.E.R.: Call of Pripyat unfold shortly after the end of S.T.A.L.K.E.R.: Shadow of Chernobyl. Having discovered about the open path to the Zone center, the government decides to hold a large-scale military "Fairway" operation aimed to take the CNPP under control.

According to the operation''s plan, the first military group is to conduct an air scouting of the territory to map out the detailed layouts of anomalous fields location. Thereafter, making use of the maps, the main military forces are to be dispatched. Despite thorough preparations, the operation fails. Most of the avant-garde helicopters crash. In order to collect information on reasons behind the operation failure, Ukraine''s Security Service sends their agent into the Zone center.

From now on, everything depends on you.', 'https://www.igdb.com/games/s-dot-t-a-dot-l-k-dot-e-r-dot-call-of-pripyat', '["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 9.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
