INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6498, NULL, NULL, 26472, 'Disco Elysium', 'Disco Elysium', 'game', 2019, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1sfj.jpg', NULL, 'Disco Elysium is a role-playing game developed and published by ZA/UM. It is set in the fictional city of Revachol, where players assume the role of an amnesic detective investigating a murder. The game emphasizes dialogue and skill-based choices, with character attributes represented by internal voices that influence decisions and interactions. Its narrative explores themes of politics, philosophy, and personal identity, and it is known for its unconventional gameplay and deep storytelling.', 'https://www.igdb.com/games/disco-elysium', '["PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
