INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6501, 170687, 'tt0787474', NULL, 'The Boxtrolls', 'The Boxtrolls', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/npBf0yc5Gt7aAyyVOcYtFyT2IPa.jpg', 'https://image.tmdb.org/t/p/original/q2vz5DeLbegD2teJU29Gtb4t2sO.jpg', 'An orphaned boy raised by underground creatures called Boxtrolls comes up from the sewers and out of his box to save his family and the town from the evil exterminator, Archibald Snatcher.', NULL, NULL, 5.2897, 6.7, 0, 2.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6502, NULL, NULL, 1339, 'Psychonauts', 'Psychonauts', 'game', 2005, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob7ms.jpg', NULL, 'Psychonauts is a platform-adventure game developed by Double Fine Productions and released in 2005. It follows Razputin “Raz” Aquato, a young psychic who runs away from the circus to attend a summer camp for aspiring psychonauts. Players explore imaginative levels set inside the minds of different characters, each reflecting their mental states. Gameplay combines platforming, combat, and the use of psychic abilities such as telekinesis and levitation. The game was praised for its creativity, humor, and distinctive art style.', 'https://www.igdb.com/games/psychonauts', '["Xbox", "PlayStation 3", "PlayStation 4", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360", "Xbox One", "PlayStation 2"]', NULL, NULL, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6503, 14165, 'tt0946601', NULL, 'Ruby Gloom', 'Ruby Gloom', 'tv', 2006, 'https://image.tmdb.org/t/p/w500/tnUpRoi4Z9BYthmjM9CCRwPR5vN.jpg', 'https://image.tmdb.org/t/p/original/cxwVDVEkIrIDoXdHtrO50RFxfs.jpg', 'Ruby Gloom is a Canadian children''s show that revolves around the titular character, Ruby, who has a unique perspective on the world. While some kids might be afraid of the dark, Ruby embraces it and finds joy in the company of strange and quirky characters like Doom Kitty, Skull Boy, Misery, Boo Boo, and Mr. Buns. Together, they navigate various adventures and challenges. The series is based on an apparel franchise of the same name. The show was produced by Nelvana and began airing on October 13, 2006 in Canada on the network YTV. It features the voices of Sarah Gadon, Emily Hampshire, Peter Keleghan, and Adrian Truss.', NULL, NULL, 5.2898, 7.2, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6504, 11497, 'tt0096787', NULL, 'All Dogs Go to Heaven', 'All Dogs Go to Heaven', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/nmWh1NglDinfkHD9zCNqGWyhl7Q.jpg', 'https://image.tmdb.org/t/p/original/haJ6SsjxfhSRG61LMy4QJWxCNAb.jpg', 'When a casino-owning dog named Charlie is murdered by his rival Carface, he finds himself in Heaven. Wanting to get back at his killer, he cons his way back to the living with the warning that doing so damns him to Hell. Once back, he teams with his old partner, Itchy, to prep his retaliation. He stumbles upon an orphan girl who can talk to the animals, thus allowing him to get the inside info on the races to ensure his wins to finance his plans. However, all the while, he is still haunted by nightmares of what''s waiting for him on the other side unless he can prove that he is worthy of Heaven again.', NULL, NULL, 5.0755, 6.835, 0, 2.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6505, 56021, 'tt0112065', NULL, 'The Maxx', 'The Maxx', 'tv', 1995, 'https://image.tmdb.org/t/p/w500/ckDgOhXdWS9TZPydx2oqYtdh1YZ.jpg', 'https://image.tmdb.org/t/p/original/mlaQXX7rYlpom7QTmJvfkUAOIih.jpg', 'Maxx is a purple-clad superhero living in a cardboard box. His only friend is Julie Winters, a freelance social worker. Maxx often finds himself shifting back and forth between the "real" world and a more primitive outback world where he rules, and protects Julie. Mr. Gone, a self-proclaimed "student of the mystic arts" seems to know more about Maxx and Julie and their strange relationship than they could ever guess, but he''s not exactly telling all....not yet, anyway.', NULL, NULL, 2.3206, 8.243, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
