INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6507, 9078, 'tt0057546', NULL, 'The Sword in the Stone', 'The Sword in the Stone', 'movie', 1963, 'https://image.tmdb.org/t/p/w500/7lyeeuhGAJSNXYEW34S8mJ1bwI8.jpg', 'https://image.tmdb.org/t/p/original/uMe6McFXAPEhkasGVlaLTOuhfnl.jpg', 'Wart is a young boy who aspires to be a knight''s squire. On a hunting trip he falls in on Merlin, a powerful but amnesiac wizard who has plans for him beyond mere squiredom. He starts by trying to give him an education, believing that once one has an education, one can go anywhere. Needless to say, it doesn''t quite work out that way.', NULL, NULL, 6.0149, 7.227, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
