INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6515, 20224, 'tt0790618', NULL, 'Remember the Daze', 'Remember the Daze', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/nQajjglgJ6liZnVo6jeNzlkn9Na.jpg', 'https://image.tmdb.org/t/p/original/zNnCdjKsNXkkB78mEeuJT2KQVPI.jpg', 'During the summer of 1999, a group of teenagers, through interconnected narratives, live through their last day of high school and prepare for the future. Holly, once the new girl in school, does whatever it takes to remain popular. Dawn, who is secretly a lesbian, battles drugs. Tori is the valedictorian of her class, but, on the eve of graduation, she decides to experiment with drugs for the first time.', NULL, NULL, 0.9722, 4.868, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6516, 16996, 'tt0974661', NULL, '17 Again', '17 Again', 'movie', 2009, 'https://image.tmdb.org/t/p/w500/yEcfFXEWpuXcfsR9nKESVCFneqV.jpg', 'https://image.tmdb.org/t/p/original/8urrLPW6HFaIuRhJ1G3iQ7usEo7.jpg', 'On the brink of a midlife crisis, 30-something Mike O''Donnell wishes he could have a "do-over." And that''s exactly what he gets when he wakes up one morning to find he''s 17 years old again. With his adult mind stuck inside the body of a teenager, Mike actually has the chance to reverse some decisions he wishes he''d never made. But maybe they weren''t so bad after all.', NULL, NULL, 8.6653, 6.319, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6517, 266082, 'tt3655522', NULL, 'Girlhood', 'Bande de filles', 'movie', 2014, 'https://image.tmdb.org/t/p/w500/qZ52DlSVguX0WHYoiOD464IIONd.jpg', 'https://image.tmdb.org/t/p/original/yJ9HQ4OrFouSj8kRF9opf8s7yGE.jpg', 'Oppressed by her family setting, dead-end school prospects and the boys law in the neighborhood, Marieme starts a new life after meeting a group of three free-spirited girls. She changes her name, her dress code, and quits school to be accepted in the gang, hoping that this will be a way to freedom.', NULL, NULL, 1.3045, 6.447, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
