INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6519, 13078, 'tt0796302', NULL, 'The Babysitters', 'The Babysitters', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/nsrNUqGXI95unRKZEu8BJ584xWn.jpg', 'https://image.tmdb.org/t/p/original/hKHX04i2zQrgZJdxS9UuFsgPUd7.jpg', 'Seventeen-year-old Shirley is a good student who works as a babysitter in order to make money for college. One night Michael, a father Shirley works for, confesses he''s unhappy with married life. Shirley has a crush on Michael, and seizes this moment to kiss him. Michael is so happy he presents Shirley with a big tip, which gives her an idea. Shirley plans to make extra money by setting up her teenage friends with other unhappy fathers.', NULL, NULL, 3.9766, 6.002, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
