INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6521, 15037, 'tt0127723', NULL, 'Can''t Hardly Wait', 'Can''t Hardly Wait', 'movie', 1998, 'https://image.tmdb.org/t/p/w500/r3a5gGWfS0SDS9nriNrJzSSrErf.jpg', 'https://image.tmdb.org/t/p/original/yPVhkvOiI4UZC0jOpjO1HntlxHv.jpg', 'It''s graduation day at Huntington Hills High, and you know what that means - time to party. And not just any party, either. This one will be a night to remember, as the nerds become studs, the jocks are humiliated, and freshman crushes blossom into grown-up romance.', NULL, NULL, 2.4322, 6.238, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
