INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6542, 4967, 'tt0171433', NULL, 'Keeping the Faith', 'Keeping the Faith', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/9NF199FTvHr9ggqdBTVbPhF1MGk.jpg', 'https://image.tmdb.org/t/p/original/3xJFFU3YF9WcpK2WXDF15zVcSQZ.jpg', 'Best friends since they were kids, Rabbi Jacob Schram and Father Brian Finn are dynamic and popular young men living and working on New York''s Upper West Side. When Anna Reilly, once their childhood friend and now grown into a beautiful corporate executive, suddenly returns to the city, she reenters Jake and Brian''s lives and hearts with a vengeance. Sparks fly and an unusual and complicated love triangle ensues.', NULL, NULL, 1.5283, 6.102, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6543, 16553, 'tt0412922', NULL, 'Little Manhattan', 'Little Manhattan', 'movie', 2005, 'https://image.tmdb.org/t/p/w500/z0RNI1NMtsvLsuTo1rWZfNHVs1z.jpg', 'https://image.tmdb.org/t/p/original/f5XOH9b9oV7yzIqhKDEXtDx0uz9.jpg', 'Ten-year-old Gabe Burton is just an average kid growing up in Manhattan until Rosemary Telesco walks into his karate class. But before Gabe can tell Rosemary how he feels, she reveals that she won''t be going to public school any more. Gabe has a lot more to learn about life, love, and girls.', NULL, NULL, 2.4413, 7.205, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
