INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (6546, 13150, 'tt0482572', NULL, 'Pride and Glory', 'Pride and Glory', 'movie', 2008, 'https://image.tmdb.org/t/p/w500/8VZ1ABbtXqwPcc06yXbf3gj3anG.jpg', 'https://image.tmdb.org/t/p/original/aCeEEogpHzGjY3CE1ct7uhL11X4.jpg', 'A saga centered on the Tierneys, a multi-generational family of New York City Police officers. The family''s moral codes are tested when Ray Tierney investigates a case that reveals an incendiary police corruption scandal involving his own brother-in-law. For Ray, the truth is revelatory, a Pandora''s Box that threatens to upend not only the Tierney legacy but the entire NYPD.', NULL, NULL, 2.7175, 6.338, 0, 1.01, '2026-07-31 03:33:23', '2026-07-31 03:33:23');
