UPDATE "recommendations" SET "tmdb_id"=591538, "imdb_id"='tt10095582', "igdb_id"=NULL, "title"='The Tragedy of Macbeth', "original_title"='The Tragedy of Macbeth', "media_type"='movie', "release_year"=2021, "poster_url"='https://image.tmdb.org/t/p/w500/tDNJEhcLbX3jIk3BMCur9pCdaVD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lMjY6kMBOHhloz2Ul16fLJn8xuw.jpg', "overview"='Macbeth, the Thane of Glamis, receives a prophecy from a trio of witches that one day he will become King of Scotland. Consumed by ambition and spurred to action by his wife, Macbeth murders his king and takes the throne for himself.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.66, "vote_average"=6.918, "is_ambiguous"=0, "evidence_score"=12.512, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3;
