UPDATE "recommendations" SET "tmdb_id"=75612, "imdb_id"='tt1483013', "igdb_id"=NULL, "title"='Oblivion', "original_title"='Oblivion', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/bYLM3GpNUZnoFElPXp1zlhDPdtv.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2kVt8oj1cSz4GAP0Hi8SESOiH0T.jpg', "overview"='Jack Harper is one of the last few drone repairmen stationed on Earth. Part of a massive operation to extract vital resources after decades of war with a terrifying threat known as the Scavs, Jack’s mission is nearly complete. His existence is brought crashing down when he rescues a beautiful  stranger from a downed spacecraft. Her arrival triggers a chain of events that  forces him to question everything he knows and puts the fate of humanity in his hands.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.7316, "vote_average"=6.686, "is_ambiguous"=0, "evidence_score"=1.54664285714285725e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=35;
