UPDATE "recommendations" SET "tmdb_id"=7303, "imdb_id"='tt0252076', "igdb_id"=NULL, "title"='Maid in Manhattan', "original_title"='Maid in Manhattan', "media_type"='movie', "release_year"=2002, "poster_url"='https://image.tmdb.org/t/p/w500/gnEuTYH3jhHxl80QyoPfZjEYd0J.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/l5sD0AK286fBpXyDHRCbtaFMArN.jpg', "overview"='Marisa Ventura is a struggling single mom who works at a posh Manhattan hotel and dreams of a better life for her and her young son. One fateful day, hotel guest and senatorial candidate Christopher Marshall meets Marisa and mistakes her for a wealthy socialite. After an enchanting evening together, the two fall madly in love. But when Marisa''s true identity is revealed, issues of class and social status threaten to separate them. Can two people from very different worlds overcome their differences and live happily ever after?', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8077, "vote_average"=6.141, "is_ambiguous"=0, "evidence_score"=7.01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=664;
