UPDATE "recommendations" SET "tmdb_id"=671, "imdb_id"='tt0241527', "igdb_id"=NULL, "title"='Harry Potter and the Philosopher''s Stone', "original_title"='Harry Potter and the Philosopher''s Stone', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/wuMc08IPKEatf9rnMNXvIDxqP4W.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg', "overview"='Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard—with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths—and about the villain who''s to blame.', "external_url"=NULL, "platforms"=NULL, "popularity"=46.6446, "vote_average"=7.901, "is_ambiguous"=0, "evidence_score"=1.44371428571428577e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=811;
