UPDATE "recommendations" SET "tmdb_id"=1648, "imdb_id"='tt0096928', "igdb_id"=NULL, "title"='Bill & Ted''s Excellent Adventure', "original_title"='Bill & Ted''s Excellent Adventure', "media_type"='movie', "release_year"=1989, "poster_url"='https://image.tmdb.org/t/p/w500/tV25lGWGWGEqUe3U0xjQTBgilSx.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/aMASmAmkn7NT0nEq8PBZEgwBfGN.jpg', "overview"='Bill and Ted are high school buddies starting a band. They are also about to fail their history class—which means Ted would be sent to military school—but receive help from Rufus, a traveller from a future where their band is the foundation for a perfect society. With the use of Rufus'' time machine, Bill and Ted travel to various points in history, returning with important figures to help them complete their final history presentation.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.406, "vote_average"=6.844, "is_ambiguous"=0, "evidence_score"=1.36500000000000021e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=1848;
UPDATE "recommendations" SET "tmdb_id"=8367, "imdb_id"='tt0102798', "igdb_id"=NULL, "title"='Robin Hood: Prince of Thieves', "original_title"='Robin Hood: Prince of Thieves', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kuLk79GQq8WQb8fZxc6MtvIhPaC.jpg', "overview"='Nobleman crusader Robin of Locksley breaks out of a Jerusalem prison with the help of Moorish fellow prisoner Azeem and travels back home to England. But upon arrival he discovers his dead father in the ruins of his family estate, killed by the vicious sheriff of Nottingham, Robin and Azeem join forces with outlaws Little John and Will Scarlett to save the kingdom from the sheriff''s villainy.', "external_url"=NULL, "platforms"=NULL, "popularity"=9.2063, "vote_average"=6.856, "is_ambiguous"=0, "evidence_score"=7.02, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=1856;
UPDATE "recommendations" SET "tmdb_id"=895, "imdb_id"='tt0060107', "igdb_id"=NULL, "title"='Andrei Rublev', "original_title"='Андрей Рублёв', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/jUihkn16SwPPIjuOyo6orHWUep6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jqha8JCXm0aJ5SJ03Jd0JmGgWRs.jpg', "overview"='An expansive Russian drama, this film focuses on the life of revered religious icon painter Andrei Rublev. Drifting from place to place in a tumultuous era, the peace-seeking monk eventually gains a reputation for his art. But after Rublev witnesses a brutal battle and unintentionally becomes involved, he takes a vow of silence and spends time away from his work. As he begins to ease his troubled soul, he takes steps towards becoming a painter once again.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4606, "vote_average"=7.935, "is_ambiguous"=0, "evidence_score"=12.816, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=1860;
UPDATE "recommendations" SET "tmdb_id"=62177, "imdb_id"='tt1217209', "igdb_id"=NULL, "title"='Brave', "original_title"='Brave', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/1XAuDtMWpL0sYSFK0R6EZate2Ux.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qx9ts2hBYJrkIQxhryitxnLlm2u.jpg', "overview"='In the mystical Scottish Highlands, Merida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Merida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Merida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Merida''s quest — and serving as comic relief — are the kingdom''s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.', "external_url"=NULL, "platforms"=NULL, "popularity"=16.4096, "vote_average"=7.033, "is_ambiguous"=0, "evidence_score"=9.03166666666666628e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=1862;
