UPDATE "recommendations" SET "tmdb_id"=364, "imdb_id"='tt0103776', "igdb_id"=NULL, "title"='Batman Returns', "original_title"='Batman Returns', "media_type"='movie', "release_year"=1992, "poster_url"='https://image.tmdb.org/t/p/w500/jKBjeXM7iBBV9UkUcOXx3m7FSHY.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7x4SNxO5HWArighxxFeet5sn3il.jpg', "overview"='The monstrous Penguin, who dwells in the sewers beneath Gotham, joins up with corrupt mayoral candidate Max Shreck to topple the Batman once and for all. But when Shreck''s timid assistant Selina Kyle finds out, and Shreck tries to kill her, she''s transformed into the sexy Catwoman. She teams up with the Penguin and Shreck to destroy Batman, but sparks fly unexpectedly when she confronts the caped crusader.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.1068, "vote_average"=6.949, "is_ambiguous"=0, "evidence_score"=7.024, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-07-31 03:33:23' WHERE "id"=2382;
