UPDATE "recommendations" SET "tmdb_id"=1033148, "imdb_id"='tt9362736', "igdb_id"=NULL, "title"='Die My Love', "original_title"='Die My Love', "media_type"='movie', "release_year"=2025, "poster_url"='https://image.tmdb.org/t/p/w500/kajpShbFhOdpl6yCrLezMrr9tB4.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/dEkFlZzj2cb5F7SShvqkL54E4lr.jpg', "overview"='After inheriting a remote Montana house, Jackson moves there from New York with his partner Grace, and the couple soon welcome a child. As Jackson becomes increasingly absent and rural isolation sets in, Grace struggles with loneliness, creative frustration, and unresolved emotional wounds. What begins as an attempt at renewal gradually turns into an intense psychological descent, placing strain on their relationship and exposing the fragile balance between love, identity, and motherhood.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.8469, "vote_average"=6.1, "is_ambiguous"=0, "evidence_score"=6.50833333333333374e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3127;
UPDATE "recommendations" SET "tmdb_id"=208277, "imdb_id"='tt2524674', "igdb_id"=NULL, "title"='Wetlands', "original_title"='Feuchtgebiete', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/6hfZij2Nd8rCT1tezRkbzm7xWkl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jqcILemNblXGIOeg9CDCzHEBEpc.jpg', "overview"='Helen is a nonconformist teenage girl who maintains a conflictual relationship with her parents. Hanging out most of her time with her friend Corinna, with whom she breaks one social taboo after another, she uses sex as a way to rebel and break the conventional bourgeois ethic. After an intimate shaving accident, Helen ends up in the hospital where it doesn’t take long before she makes waves. But there she finds Robin, a male nurse who will sweep her off her feet...', "external_url"=NULL, "platforms"=NULL, "popularity"=1.2953, "vote_average"=5.331, "is_ambiguous"=0, "evidence_score"=2.005, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3129;
UPDATE "recommendations" SET "tmdb_id"=84184, "imdb_id"='tt1405365', "igdb_id"=NULL, "title"='Celeste & Jesse Forever', "original_title"='Celeste & Jesse Forever', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/5Cr8kW7DjZEORU8jI32bqyHSGKW.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/fKyKSmvxwMpT0qe6B0m2vbyzAOk.jpg', "overview"='Celeste and Jesse met in high school and got married young. They laugh at the same jokes and finish each other’s sentences. They are forever linked in their friends’ minds as the perfect couple – she, a high-powered businesswoman and budding novelist; he, a free spirit who keeps things from getting boring. Their only problem is that they have decided to get divorced. Can their perfect relationship withstand this minor setback?', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9777, "vote_average"=6.379, "is_ambiguous"=0, "evidence_score"=3.01333333333333319e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3140;
UPDATE "recommendations" SET "tmdb_id"=26561, "imdb_id"='tt0101811', "igdb_id"=NULL, "title"='Enchanted April', "original_title"='Enchanted April', "media_type"='movie', "release_year"=1991, "poster_url"='https://image.tmdb.org/t/p/w500/b4Jrg23Q3y7p8GS7aMnPdFiEcnP.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/hjkAO8GDwipwEL3gyItLxrfiIsw.jpg', "overview"='When married British women Rose Arbuthnot and Lottie Wilkins decide to take a break from their respective spouses, they stay at a castle in Italy for a quiet holiday. Joining the ladies is Caroline Dester, a young socialite, and Mrs. Fisher, an older aristocrat. Liberated from their daily routines, the four women ease into life in rural Italy, and each finds herself transformed by the experience.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.3406, "vote_average"=6.766, "is_ambiguous"=0, "evidence_score"=3.00333333333333341e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3146;
