UPDATE "recommendations" SET "tmdb_id"=967, "imdb_id"='tt0054331', "igdb_id"=NULL, "title"='Spartacus', "original_title"='Spartacus', "media_type"='movie', "release_year"=1960, "poster_url"='https://image.tmdb.org/t/p/w500/r0Fgg1GyZgzokaiw2HFQv3oPaL2.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9caD0fGCrp96JTFFeGyI0CGNj7.jpg', "overview"='The rebellious Thracian Spartacus, born and raised a slave, is sold to Gladiator trainer Batiatus. After weeks of being trained to kill for the arena, Spartacus turns on his owners and leads the other slaves in rebellion. As the rebels move from town to town, their numbers swell as escaped slaves join their ranks. Under the leadership of Spartacus, they make their way to southern Italy, where they will cross the sea and return to their homes.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.1346, "vote_average"=7.541, "is_ambiguous"=0, "evidence_score"=6.76, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3324;
UPDATE "recommendations" SET "tmdb_id"=652, "imdb_id"='tt0332452', "igdb_id"=NULL, "title"='Troy', "original_title"='Troy', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/a07wLy4ONfpsjnBqMwhlWTJTcm.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/y51M7Ca95sCXTCDvJaRP1uzxKbg.jpg', "overview"='In year 1250 B.C. during the late Bronze age, two emerging nations begin to clash. Paris, the Trojan prince, convinces Helen, Queen of Sparta, to leave her husband Menelaus, and sail with him back to Troy. After Menelaus finds out that his wife was taken by the Trojans, he asks his brother Agamemnon to help him get her back. Agamemnon sees this as an opportunity for power. They set off with 1,000 ships holding 50,000 Greeks to Troy.', "external_url"=NULL, "platforms"=NULL, "popularity"=60.2621, "vote_average"=7.182, "is_ambiguous"=0, "evidence_score"=10.512, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3325;
