UPDATE "recommendations" SET "tmdb_id"=409421, "imdb_id"='tt6574146', "igdb_id"=NULL, "title"='BLAME!', "original_title"='ブラム', "media_type"='movie', "release_year"=2017, "poster_url"='https://image.tmdb.org/t/p/w500/7eoRQY7VUMawwBnuD6uwN4szc8k.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9orgGrjh0Jivz0zZLn1Ufj4NRZP.jpg', "overview"='In the distant technological future, civilization has reached its ultimate Net-based form. An "infection" in the past caused the automated systems to spiral out of order, resulting in a multi-leveled city structure that replicates itself infinitely in all directions. Now humanity has lost access to the city''s controls, and is hunted down and purged by the defense system known as the Safeguard. In a tiny corner of the city, a little enclave known as the Electro-Fishers is facing eventual extinction, trapped between the threat of the Safeguard and dwindling food supplies. A girl named Zuru goes on a journey to find food for her village, only to inadvertently cause doom when an observation tower senses her and summons a Safeguard pack to eliminate the threat. With her companions dead and all escape routes blocked, the only thing that can save her now is the sudden arrival of Killy the Wanderer, on his quest for the Net Terminal Genes, the key to restoring order to the world.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8093, "vote_average"=6.5, "is_ambiguous"=0, "evidence_score"=11.0475, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3694;
UPDATE "recommendations" SET "tmdb_id"=198375, "imdb_id"='tt2591814', "igdb_id"=NULL, "title"='The Garden of Words', "original_title"='言の葉の庭', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/mXUCVq3HMtS4Y9IQ8vmEOPyN0vH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qMNmdJG0WFNXcI6hfZMQH0geHc5.jpg', "overview"='Takao, who is training to become a shoemaker, skipped school and is sketching shoes in a Japanese-style garden. He meets a mysterious woman, Yukino, who is older than him. Then, without arranging the times, the two start to see each other again and again, but only on rainy days. They deepen their relationship and open up to each other. But the end of the rainy season soon approaches.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.6406, "vote_average"=7.6, "is_ambiguous"=0, "evidence_score"=1.1004999999999999e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3708;
UPDATE "recommendations" SET "tmdb_id"=566038, "imdb_id"='tt8015444', "igdb_id"=NULL, "title"='Last and First Men', "original_title"='Last and First Men', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/7B9t8lTFCJQ6GVvSbhrbrA7nsVu.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/m76YNtzkO7G7NzQAosmu6pN1AWf.jpg', "overview"='As the end approaches inexorably, the last humans, living millions of years into the future, send a message to the humanity of the present that is both a plea for help and a warning, but also an epic tale of evolution, decline and hope.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.6196, "vote_average"=6.289, "is_ambiguous"=0, "evidence_score"=4.005, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3717;
