UPDATE "recommendations" SET "tmdb_id"=9896, "imdb_id"='tt0250687', "igdb_id"=NULL, "title"='Rat Race', "original_title"='Rat Race', "media_type"='movie', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/8ghNCfFbCJjcNSz2K5jOC3eO6ZD.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vian6RN3bC4QdBQzY1wTmBkhxVQ.jpg', "overview"='In an ensemble film about easy money, greed, manipulation and bad driving, a Las Vegas casino tycoon entertains his wealthiest high rollers -- a group that will bet on anything -- by pitting six ordinary people against each other in a wild dash for $2 million jammed into a locker hundreds of miles away. The tycoon and his wealthy friends monitor each racer''s every move to keep track of their favorites. The only rule in this race is that there are no rules.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.4769, "vote_average"=6.289, "is_ambiguous"=0, "evidence_score"=7.00285714285714267e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3750;
UPDATE "recommendations" SET "tmdb_id"=250574, "imdb_id"='tt2428170', "igdb_id"=NULL, "title"='Creep', "original_title"='Creep', "media_type"='movie', "release_year"=2014, "poster_url"='https://image.tmdb.org/t/p/w500/qn53D574tT0YRyLgirEFHQwGUXw.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AvrGwToWkP6fp13lzpxsyzoq9JH.jpg', "overview"='Looking for work, Aaron comes across a cryptic online ad: “$1,000 for the day. Filming service. Discretion is appreciated.” Low on cash and full of naiveté, he decides to go for it. He drives to a cabin in a remote mountain town where he meets Josef, his cinematic subject for the day. Josef is sincere and the project seems heartfelt, so Aaron begins to film. But as the day goes on, it becomes clear that Josef is not who he says, and his intentions are not at all pure.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.3603, "vote_average"=6.4, "is_ambiguous"=0, "evidence_score"=1.6336666666666666e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3756;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=1051, "title"='Mirror''s Edge', "original_title"='Mirror''s Edge', "media_type"='game', "release_year"=2008, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co5gbw.jpg', "backdrop_url"=NULL, "overview"='Mirror''s Edge is a first-person action-adventure game focused on parkour and free-running. Set in a heavily surveilled city, players control Faith, a courier who traverses rooftops using wall-runs, jumps, and slides to deliver sensitive information. The gameplay emphasizes momentum and fluid movement over combat, with a focus on finding the fastest path through urban environments.', "external_url"='https://www.igdb.com/games/mirror-s-edge', "platforms"='["PlayStation 3", "PC (Microsoft Windows)", "Xbox 360"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=4.505, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3769;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=2112, "title"='Mirror''s Edge Catalyst', "original_title"='Mirror''s Edge Catalyst', "media_type"='game', "release_year"=2016, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co28r2.jpg', "backdrop_url"=NULL, "overview"='Mirror''s Edge Catalyst is an action-adventure game and the reboot to Mirror''s Edge. The story in the game explores the past of the protagonist Faith. Like in the previous game, the main gameplay in Mirror''s Edge Catalyst involves traversing the city using parkour to reach certain objectives. Unlike the linear levels in Mirror''s Edge, Mirror''s Edge Catalyst features an open-world free-roaming environment. Combat has been overhauled and emphasized compared to the first game and Catalyst no longer allows the player to use weapons, instead focusing on melee attacks.', "external_url"='https://www.igdb.com/games/mirrors-edge-catalyst', "platforms"='["PlayStation 4", "PC (Microsoft Windows)", "Xbox One"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=4.505, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=3770;
