UPDATE "recommendations" SET "tmdb_id"=77, "imdb_id"='tt0209144', "igdb_id"=NULL, "title"='Memento', "original_title"='Memento', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/nzlv62aC0octS5AklAiWpXLX9Z0.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/7Wev9JMo6R5XAfz2KDvXb7oPMmy.jpg', "overview"='Leonard Shelby is tracking down the man who raped and murdered his wife. The difficulty of locating his wife''s killer, however, is compounded by the fact that he suffers from a rare, untreatable form of short-term memory loss. Although he can recall details of life before his accident, Leonard cannot remember what happened fifteen minutes ago, where he''s going, or why.', "external_url"=NULL, "platforms"=NULL, "popularity"=23.8675, "vote_average"=8.175, "is_ambiguous"=0, "evidence_score"=6.51, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4037;
