UPDATE "recommendations" SET "tmdb_id"=19898, "imdb_id"='tt1188729', "igdb_id"=NULL, "title"='Pandorum', "original_title"='Pandorum', "media_type"='movie', "release_year"=2009, "poster_url"='https://image.tmdb.org/t/p/w500/mNMfa6r3pl0EzFIKEkVcxyr6Rc7.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/eWRct17fMmra8T9yQEcwudoNxUW.jpg', "overview"='Two crew members wake up on an abandoned spacecraft with no idea who they are, how long they''ve been asleep, or what their mission is. The two soon discover they''re actually not alone – and the reality of their situation is more horrifying than they could have imagined.', "external_url"=NULL, "platforms"=NULL, "popularity"=4.3355, "vote_average"=6.596, "is_ambiguous"=0, "evidence_score"=1.97299999999999968e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4059;
