UPDATE "recommendations" SET "tmdb_id"=85723, "imdb_id"='tt9170108', "igdb_id"=NULL, "title"='Raised by Wolves', "original_title"='Raised by Wolves', "media_type"='tv', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/mTvSVKMn2Npf6zvYNbGMJnYLtvp.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/na2xUduK8HviOFT97TiFG2MkJmY.jpg', "overview"='After Earth is ravaged by a great religious war, an atheistic android architect sends two of his creations, Mother and Father, to start a peaceful, godless colony on the planet Kepler-22b. Their treacherous task is jeopardized by the arrival of the Mithraic, a deeply devout religious order of surviving humans.', "external_url"=NULL, "platforms"=NULL, "popularity"=12.5021, "vote_average"=7.506, "is_ambiguous"=0, "evidence_score"=3.00666666666666682e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4068;
UPDATE "recommendations" SET "tmdb_id"=2697, "imdb_id"='tt0078682', "igdb_id"=NULL, "title"='Sapphire & Steel', "original_title"='Sapphire & Steel', "media_type"='tv', "release_year"=1979, "poster_url"='https://image.tmdb.org/t/p/w500/4MTGI5vc1FQBkSG83Jo9SO6jzLo.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/gfTsTgm6MXn7IMFsr9kvaXGae3R.jpg', "overview"='Sapphire & Steel is a British television science-fiction fantasy series starring David McCallum as Steel and Joanna Lumley as Sapphire. Produced by ATV, it ran from 1979 to 1982 on the ITV network. The series was created by Peter J. Hammond who conceived the programme under the working title The Time Menders, after a stay in an allegedly haunted castle. Hammond also wrote all the stories except for the fifth, which was co-written by Don Houghton and Anthony Read.

None of the stories had onscreen titles, or any official titles assigned by the writers. The Region 1 Complete Series DVD release gives the titles "Escape Through a Crack in Time", "The Railway Station", "The Creature''s Revenge", "The Man Without a Face", "Dr. McDee Must Die" and "The Trap", respectively. These titles have often been cited as having been created by science fiction magazine Time Screen.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7843, "vote_average"=7.269, "is_ambiguous"=0, "evidence_score"=9.00333333333333385e+00, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4085;
UPDATE "recommendations" SET "tmdb_id"=18123, "imdb_id"='tt1660055', "igdb_id"=NULL, "title"='Scooby-Doo! Mystery Incorporated', "original_title"='Scooby-Doo! Mystery Incorporated', "media_type"='tv', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/mu8zU2jQfPbGO5bC6RHYrSypxUd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2VvLk11UlmdHFPQkDgm4KPSjLrs.jpg', "overview"='This incarnation of the popular cartoon series finds Scooby and the gang living in Crystal Cove, a small town with a long history of ghost sightings, monster tales and other mysteries ripe for the sleuths to solve once and for all. But the longstanding Crystal Cove residents, who bank on the town''s reputation to attract tourists, are prepared to do what it takes to protect their turf.', "external_url"=NULL, "platforms"=NULL, "popularity"=29.4764, "vote_average"=8.232, "is_ambiguous"=0, "evidence_score"=8.206, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4086;
