UPDATE "recommendations" SET "tmdb_id"=2787, "imdb_id"='tt0134847', "igdb_id"=NULL, "title"='Pitch Black', "original_title"='Pitch Black', "media_type"='movie', "release_year"=2000, "poster_url"='https://image.tmdb.org/t/p/w500/3AnlxZ5CZnhKKzjgFyY6EHxmOyl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/bMJdVmo6QqoUHpUsjWyei6MN02x.jpg', "overview"='When their ship crash-lands on a remote planet, the marooned passengers soon learn that escaped convict Riddick isn''t the only thing they have to fear. Deadly creatures lurk in the shadows, waiting to attack in the dark, and the planet is rapidly plunging into the utter blackness of a total eclipse. With the body count rising, the doomed survivors are forced to turn to Riddick with his eerie eyes to guide them through the darkness to safety. With time running out, there''s only one rule: Stay in the light.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.8966, "vote_average"=6.867, "is_ambiguous"=0, "evidence_score"=9.09125, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4097;
