UPDATE "recommendations" SET "tmdb_id"=580633, "imdb_id"='tt4522922', "igdb_id"=NULL, "title"='Tales from the Lodge', "original_title"='Tales from the Lodge', "media_type"='movie', "release_year"=2019, "poster_url"='https://image.tmdb.org/t/p/w500/mQUIAwsebsOEq7CR8KUfM8HP9ft.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/lGEQgPswUFSTvJfb9WCfNSCTiFQ.jpg', "overview"='Tales From The Lodge is a fresh take on the portmanteau horror-comedy genre. An isolated lodge somewhere in England. Five old university pals, now nudging 40, gather for a weekend to scatter the ashes of their friend, Jonesy, who drowned himself in the lake three years earlier. They settle in for a fun evening, entertaining each other with stories of murders, ghosts, zombies and possessions, but as day turns to night, the gang become aware of another horror story unfolding around them - And this one is real.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.7526, "vote_average"=5.404, "is_ambiguous"=0, "evidence_score"=4.005, "created_at"='2026-07-21 03:32:24', "updated_at"='2026-07-31 03:33:23' WHERE "id"=4805;
