UPDATE "recommendations" SET "tmdb_id"=84327, "imdb_id"='tt2125666', "igdb_id"=NULL, "title"='The Queen of Versailles', "original_title"='The Queen of Versailles', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/eFMRyapxD7XP5Boj6CLaDtQ1m3o.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9kjM8bRLcMRhOgX3z6MVw24n5Al.jpg', "overview"='With the epic dimensions of a Shakespearean tragedy, The Queen of Versailles follows billionaires Jackie and David’s rags-to-riches story to uncover the innate virtues and flaws of their American dream. We open on the triumphant construction of the biggest house in America, a sprawling, 90,000-square-foot mansion inspired by Versailles. Since a booming time-share business built on the real-estate bubble is financing it, the economic crisis brings progress to a halt and seals the fate of its owners. We witness the impact of this turn of fortune over the next two years in a riveting film fraught with delusion, denial, and self-effacing humor.', "external_url"=NULL, "platforms"=NULL, "popularity"=0.9929, "vote_average"=6.912, "is_ambiguous"=0, "evidence_score"=2.055, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-07-31 03:33:23' WHERE "id"=5591;
UPDATE "recommendations" SET "tmdb_id"=11662, "imdb_id"='tt0405821', "igdb_id"=NULL, "title"='Casshern', "original_title"='CASSHERN', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/naIjHWfQFge69GqeehgsekwDkbl.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nOovQqWWrGRkEkefR19syGO5a9i.jpg', "overview"='Fifty years of war between the Great Eastern Federation and Europa - now merged as Eurasia - have taken their toll on planet Earth. As a result of the use of biological, chemical and nuclear weapons, much of Earth has become uninhabitable and people have become prey to new diseases. Professor Azuma''s "neo-cell" project, which is supposed to be the answer to mankind''s hardships, becomes a nightmare come true when mutants spawned from the experiment escape and declare war on the human race. Azuma''s son Tetsuya, who was killed during the previous war, is reborn into the cyborg Casshern as mankind''s last hope against the new mutant threat. This live-action sci-fi movie based on a 1973 Japanese animé of the same name.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.8794, "vote_average"=5.895, "is_ambiguous"=0, "evidence_score"=2.015, "created_at"='2026-07-29 20:51:09', "updated_at"='2026-07-31 03:33:23' WHERE "id"=5622;
